-- Explicitly install in a dedicated game database. Never use the zones database.
-- Game rules, RNG and wallet decisions remain in the Render product process.
CREATE SCHEMA IF NOT EXISTS croupier_game;
CREATE SCHEMA IF NOT EXISTS croupier_auth;
CREATE TABLE croupier_game.players (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'USD',
 balance NUMERIC NOT NULL DEFAULT 1000, created_at TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','blocked','closed')),
 account_epoch BIGINT NOT NULL DEFAULT 0, closed_at TEXT
);
CREATE TABLE croupier_game.transactions (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, player_id TEXT NOT NULL REFERENCES croupier_game.players(id),
 type TEXT NOT NULL, amount NUMERIC NOT NULL, currency TEXT NOT NULL, meta TEXT, at TEXT NOT NULL
);
CREATE INDEX transactions_player_id_id ON croupier_game.transactions(player_id,id);
CREATE TABLE croupier_game.blackjack_tables (player_id TEXT PRIMARY KEY REFERENCES croupier_game.players(id), state TEXT NOT NULL);
CREATE TABLE croupier_game.native_presentations (player_id TEXT PRIMARY KEY REFERENCES croupier_game.players(id), request_id TEXT NOT NULL, version INTEGER NOT NULL, payload TEXT NOT NULL);
CREATE TABLE croupier_game.player_accounts (email TEXT PRIMARY KEY, player_id TEXT UNIQUE NOT NULL REFERENCES croupier_game.players(id), salt TEXT NOT NULL, hash TEXT NOT NULL);
CREATE TABLE croupier_game.player_sessions (digest TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES croupier_game.players(id), expires BIGINT NOT NULL, source_stamp TEXT, display_name TEXT);
CREATE INDEX player_sessions_player ON croupier_game.player_sessions(player_id);
CREATE TABLE croupier_game.craig_player_links (craig_user_id TEXT PRIMARY KEY, player_id TEXT UNIQUE NOT NULL REFERENCES croupier_game.players(id));
CREATE TABLE croupier_game.bo_game_handoffs (state_digest TEXT PRIMARY KEY, next_path TEXT NOT NULL, expires BIGINT NOT NULL, code_digest TEXT UNIQUE, craig_user_id TEXT, username TEXT, source_stamp TEXT, session_until BIGINT);
CREATE TABLE croupier_game.preview_sessions (digest TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES croupier_game.players(id), expires BIGINT NOT NULL);
CREATE TABLE croupier_game.lissabon_profiles (player_id TEXT PRIMARY KEY REFERENCES croupier_game.players(id), name_key TEXT UNIQUE NOT NULL);
CREATE TABLE croupier_game.lissabon_profile_sessions (digest TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES croupier_game.players(id), expires BIGINT NOT NULL);
CREATE TABLE croupier_game.player_chat_memory_meta (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE croupier_game.player_chat_memory_profiles (player_ref TEXT NOT NULL,dealer_id TEXT NOT NULL,history TEXT NOT NULL,revision TEXT NOT NULL,touched BIGINT NOT NULL,PRIMARY KEY(player_ref,dealer_id));
CREATE TABLE croupier_game.player_chat_memory_requests (player_ref TEXT NOT NULL,dealer_id TEXT NOT NULL,request_ref TEXT NOT NULL,fingerprint TEXT NOT NULL,reservation TEXT NOT NULL,profile_revision TEXT NOT NULL,state TEXT NOT NULL,started BIGINT NOT NULL,result_fingerprint TEXT,committed_revision TEXT,PRIMARY KEY(player_ref,dealer_id,request_ref));
CREATE INDEX player_chat_memory_request_age ON croupier_game.player_chat_memory_requests(started);
CREATE TABLE croupier_game.player_probe_profiles (scope TEXT PRIMARY KEY,epoch BIGINT NOT NULL,generation TEXT NOT NULL,activity BIGINT NOT NULL,sampled BIGINT,policy TEXT,reason TEXT NOT NULL,messages INTEGER NOT NULL DEFAULT 0,extraction_at BIGINT NOT NULL DEFAULT 0);
CREATE TABLE croupier_game.player_probe_sessions (scope TEXT NOT NULL,session TEXT NOT NULL,tab TEXT NOT NULL,seen BIGINT NOT NULL,flags TEXT NOT NULL,PRIMARY KEY(scope,session,tab));
CREATE TABLE croupier_game.player_probe_attempts (scope TEXT NOT NULL,id TEXT NOT NULL,epoch BIGINT NOT NULL,generation TEXT NOT NULL,session TEXT NOT NULL,tab TEXT NOT NULL,policy TEXT NOT NULL,started BIGINT NOT NULL,state TEXT NOT NULL,text TEXT NOT NULL DEFAULT '',topic TEXT NOT NULL DEFAULT '',memories TEXT NOT NULL DEFAULT '[]',played BIGINT,memory_revision TEXT NOT NULL,evidence TEXT NOT NULL DEFAULT '[]',PRIMARY KEY(scope,id));
CREATE INDEX player_probe_attempt_age ON croupier_game.player_probe_attempts(started);
CREATE TABLE croupier_game.player_probe_sources (scope TEXT NOT NULL,id TEXT NOT NULL,text TEXT NOT NULL,created BIGINT NOT NULL,PRIMARY KEY(scope,id));
CREATE TABLE croupier_game.player_probe_facts (scope TEXT NOT NULL,id TEXT NOT NULL,topic TEXT NOT NULL,type TEXT NOT NULL,content TEXT NOT NULL,source TEXT NOT NULL,created BIGINT NOT NULL,expires BIGINT NOT NULL,not_before BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(scope,id));
CREATE TABLE croupier_game.player_probe_rounds (scope TEXT NOT NULL,id TEXT NOT NULL,sequence BIGINT NOT NULL,hands TEXT NOT NULL,completed BIGINT NOT NULL,PRIMARY KEY(scope,id));
CREATE TABLE croupier_game.partner_rounds (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,key_id TEXT NOT NULL,player_id TEXT NOT NULL REFERENCES croupier_game.players(id),partner_player TEXT NOT NULL,table_version INTEGER,shoe_id TEXT,op TEXT NOT NULL,request_id TEXT,stake NUMERIC,delta NUMERIC,currency TEXT,view TEXT,at TEXT NOT NULL);
CREATE TABLE croupier_game.partner_players (key_id TEXT NOT NULL,partner_player TEXT NOT NULL,player_id TEXT NOT NULL REFERENCES croupier_game.players(id),PRIMARY KEY(key_id,partner_player));
CREATE TABLE croupier_game.partner_idem (key_id TEXT NOT NULL,request_id TEXT NOT NULL,response TEXT NOT NULL,PRIMARY KEY(key_id,request_id));
CREATE TABLE croupier_game.player_admin_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,player_id TEXT NOT NULL REFERENCES croupier_game.players(id),actor TEXT NOT NULL,action TEXT NOT NULL,reason TEXT NOT NULL,previous_status TEXT,status TEXT NOT NULL,at TEXT NOT NULL);
CREATE TABLE croupier_auth.users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username TEXT UNIQUE NOT NULL,email TEXT,salt TEXT,hash TEXT,role TEXT NOT NULL DEFAULT 'reader',created_at TEXT NOT NULL);
CREATE TABLE croupier_auth.tokens (token TEXT PRIMARY KEY,username TEXT NOT NULL,kind TEXT NOT NULL,exp BIGINT NOT NULL);
CREATE TABLE croupier_auth.meta (k TEXT PRIMARY KEY,v TEXT NOT NULL);
CREATE TABLE croupier_auth.bo_auth_epochs (user_id BIGINT PRIMARY KEY,epoch BIGINT NOT NULL DEFAULT 0);
CREATE TABLE croupier_auth.bo_lab_handoffs (state_digest TEXT PRIMARY KEY,next_path TEXT NOT NULL DEFAULT '/',expires BIGINT NOT NULL,code_digest TEXT UNIQUE,craig_user_id TEXT,role TEXT,source_stamp TEXT,auth_epoch BIGINT,session_until BIGINT);
CREATE TABLE croupier_auth.lab_sessions (token_digest TEXT PRIMARY KEY,craig_user_id TEXT NOT NULL,role TEXT NOT NULL,source_stamp TEXT NOT NULL,auth_epoch BIGINT,expires BIGINT NOT NULL);
CREATE TABLE croupier_auth.api_keys (id TEXT PRIMARY KEY,name TEXT NOT NULL,key TEXT UNIQUE NOT NULL,secret TEXT NOT NULL,scopes TEXT NOT NULL,wallet_url TEXT,ip_allow TEXT,created_by TEXT,created_at TEXT NOT NULL,last_used TEXT,revoked_at TEXT);
CREATE FUNCTION croupier_auth.bump_auth_epoch() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  INSERT INTO croupier_auth.bo_auth_epochs(user_id,epoch) VALUES(OLD.id,1) ON CONFLICT(user_id) DO UPDATE SET epoch=croupier_auth.bo_auth_epochs.epoch+1;
 ELSIF OLD.role IS DISTINCT FROM NEW.role OR OLD.salt IS DISTINCT FROM NEW.salt OR OLD.hash IS DISTINCT FROM NEW.hash THEN
  INSERT INTO croupier_auth.bo_auth_epochs(user_id,epoch) VALUES(NEW.id,1) ON CONFLICT(user_id) DO UPDATE SET epoch=croupier_auth.bo_auth_epochs.epoch+1;
 END IF;
 RETURN NULL;
END $$;
CREATE TRIGGER bo_auth_epoch_update AFTER UPDATE OF role,salt,hash ON croupier_auth.users FOR EACH ROW EXECUTE FUNCTION croupier_auth.bump_auth_epoch();
CREATE TRIGGER bo_auth_epoch_delete AFTER DELETE ON croupier_auth.users FOR EACH ROW EXECUTE FUNCTION croupier_auth.bump_auth_epoch();
CREATE TABLE croupier_game.storage_migrations (version TEXT PRIMARY KEY,checksum TEXT NOT NULL,source_hashes TEXT NOT NULL,applied_at TEXT NOT NULL);
